1	import type { Meta, StoryObj } from '@storybook/react-webpack5';
2	import { ZimmSlideIndicator } from './index';
3	
4	const meta: Meta<typeof ZimmSlideIndicator> = {
5	  title: 'Commerce/ZimmSlideIndicator',
6	  component: ZimmSlideIndicator,
7	  parameters: { layout: 'padded' },
8	};
