import React from 'react';
import { describe, test, expect, vi } from 'vitest';
import { render, screen, within } from '@testing-library/react';
import { IntlProvider } from 'react-intl';
import { ZimmSizeChipGroup } from './index';
import type { ZimmSizeChipValue } from './index';

vi.mock('@chakra-ui/react', async (importOriginal) => {
  const actual = await importOriginal<typeof import('@chakra-ui/react')>();
  return { ...actual, useMultiStyleConfig: () => ({ radiogroup: {}, oneSize: {} }) };
});

const wrap = (ui: React.ReactElement) =>
  render(<IntlProvider locale="en" defaultLocale="en">{ui}</IntlProvider>);

const val = (value: string, label: string, over: Partial<ZimmSizeChipValue> = {}): ZimmSizeChipValue => ({
  value,
  label,
  ...over,
});

const FOUR = [val('xs', 'XS'), val('s', 'S'), val('m', 'M'), val('l', 'L')];

describe('PROBE — re-render with changed selectedValue prop', () => {
  test('roving tabindex moves to the new selectedValue after a prop-driven rerender (no remount)', () => {
    const { rerender } = wrap(<ZimmSizeChipGroup values={FOUR} selectedValue="xs" />);
    let stops = screen.getAllByRole('radio').filter((el) => el.getAttribute('tabindex') === '0');
    expect(stops).toHaveLength(1);
    expect(stops[0]).toHaveTextContent('XS');

    // Same component instance, new selectedValue prop — simulates a controlling page
    // navigating to a different variation param.
    rerender(
      <IntlProvider locale="en" defaultLocale="en">
        <ZimmSizeChipGroup values={FOUR} selectedValue="l" />
      </IntlProvider>,
    );

    stops = screen.getAllByRole('radio').filter((el) => el.getAttribute('tabindex') === '0');
    expect(stops).toHaveLength(1);
    expect(stops[0]).toHaveTextContent('L');
  });

  test('roving tabindex recomputes when the SAME selectedValue becomes disabled on rerender', () => {
    const initial = [val('xs', 'XS'), val('s', 'S'), val('m', 'M')];
    const { rerender } = wrap(<ZimmSizeChipGroup values={initial} selectedValue="s" />);
    let stops = screen.getAllByRole('radio').filter((el) => el.getAttribute('tabindex') === '0');
    expect(stops[0]).toHaveTextContent('S');

    const nowDisabled = [val('xs', 'XS'), val('s', 'S', { isDisabled: true }), val('m', 'M')];
    rerender(
      <IntlProvider locale="en" defaultLocale="en">
        <ZimmSizeChipGroup values={nowDisabled} selectedValue="s" />
      </IntlProvider>,
    );

    stops = screen.getAllByRole('radio').filter((el) => el.getAttribute('tabindex') === '0');
    expect(stops).toHaveLength(1);
    // 's' is still nominally "selected" but is now disabled -- roving tabindex must move off it.
    expect(stops[0]).not.toHaveAttribute('data-size-value', 's');
  });
});
